// Ported from Limbophobia src/items/worldSystems.ts (same author): its texture painters only; the geometry and game code stay there.
// Generated by the material library's extractor and then kept by hand. Paints at 32 px per metre (src/gfx/mat/atlas.ts).
import { addTextureModule } from '../../textures/index';
import { atlas } from '../../atlas';

// ---------------------------------------------------------------- fx textures
addTextureModule(() => {
  atlas().add('fx_flame', 8, 16, (pc) => {
    pc.wrap = false;
    for (let y = 0; y < 16; y++) for (let x = 0; x < 8; x++) {
      const cx = Math.abs(x + 0.5 - 4) / 4, t = y / 16; // t: 0 top .. 1 bottom
      const w = 0.25 + t * 0.75;
      if (cx > w) continue;
      const core = cx < w * 0.45 && t > 0.35;
      pc.set(x, y, core ? (t > 0.75 ? 0xfff6c0 : 0xffd060) : t > 0.6 ? 0xff8a20 : 0xe04a10);
    }
  });
  atlas().add('fx_rain', 2, 8, (pc) => { pc.fill(0x9ab4d0); pc.set(0, 0, 0xd8e8f8); });
});
